  "時間範圍": {"en": "Time range", "ja": "時間範囲", "fr": "Plage horaire", "de": "Zeitraum", "it": "Intervallo di tempo", "es": "Rango de tiempo", "pt-BR": "intervalo de tempo", "ko": "시간 범위", "ru": "временной диапазон", "id": "rentang waktu", "vi": "phạm vi thời gian", "th": "ช่วงเวลา", "tr": "zaman aralığı", "nl": "tijdsbereik", "pl": "zakres czasu", "uk": "діапазон часу", "hi": "समय सीमा", "bn": "সময় পরিসীমা", "ms": "julat masa", "fil": "saklaw ng oras", "sv": "tidsintervall"},
