  "帳戶扣點": {"en": "Account credits", "ja": "アカウントのクレジット", "fr": "Crédits du compte", "de": "Kontoguthaben", "it": "Crediti dell’account", "es": "Créditos de la cuenta", "pt-BR": "Pontos de dedução da conta", "ko": "계좌 공제 포인트", "ru": "Списание баллов со счета", "id": "Poin pengurangan akun", "vi": "Điểm trừ tài khoản", "th": "คะแนนหักบัญชี", "tr": "Hesap kesinti noktaları", "nl": "Rekeningaftrekpunten", "pl": "Punkty odliczeniowe konta", "uk": "Бали відрахувань з рахунку", "hi": "खाता कटौती अंक", "bn": "অ্যাকাউন্ট কাটানোর পয়েন্ট", "ms": "Mata potongan akaun", "fil": "Mga puntos sa pagbabawas ng account", "sv": "Kontoavdragspoäng"},
  "需登入": {"en": "Sign-in required", "ja": "ログインが必要です", "fr": "Connexion requise", "de": "Anmeldung erforderlich", "it": "Accesso richiesto", "es": "Se requiere iniciar sesión", "pt-BR": "Login necessário", "ko": "로그인이 필요합니다", "ru": "Требуется вход", "id": "Diperlukan login", "vi": "Yêu cầu đăng nhập", "th": "ต้องเข้าสู่ระบบ", "tr": "Giriş gerekli", "nl": "Inloggen vereist", "pl": "Wymagane logowanie", "uk": "Необхідно ввійти", "hi": "लॉगिन आवश्यक है", "bn": "লগইন প্রয়োজন", "ms": "Log masuk diperlukan", "fil": "Kinakailangan ang pag-login", "sv": "Inloggning krävs"},
